/** Dotted world map. Highlighted countries pulse in the accent colour. */
export default function WorldMap({ className = "" }) {
  return (
    <svg
      className={`world-map ${className}`.trim()}
      viewBox={`0 0 ${W} ${H}`}
      preserveAspectRatio="xMidYMid meet"
      role="img"
      aria-hidden="true"
    >
      <g className="map-dim">
        {DIM.map(([x, y]) => (
          <circle key={`${x}-${y}`} cx={x + 0.5} cy={y + 0.5} r="0.44" />
        ))}
      </g>
      <g className="map-hot">
        {HOT.map(([x, y]) => (
          <circle key={`${x}-${y}`} cx={x + 0.5} cy={y + 0.5} r="0.5" />
        ))}
      </g>
    </svg>
  );
}
